    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = remaining[valid]
    trimmed_mean = np.mean(valid_rem[(valid_rem >= np.percentile(valid_rem, 25)) & (valid_rem <= np.percentile(valid_rem, 75))])
    if np.isnan(trimmed_mean):
        trimmed_mean = np.mean(valid_rem)
    relative_penalty = -((remaining - trimmed_mean) / (trimmed_mean + 1e-8)) ** 2
    return np.where(valid, relative_penalty, -np.inf)

