def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    valid_rem = remaining[valid]
    q75, q25 = np.percentile(valid_rem, [75, 25])
    iqr_midpoint = (q75 + q25) / 2.0
    iqr_penalty = -np.abs(remaining - iqr_midpoint)
    return np.where(valid, iqr_penalty, -np.inf)

