def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    original_max = np.max(bins) + 1e-8
    tightness = 1.0 - (remaining / original_max)
    balance_score = 1.0 - np.abs((bins - item) / (bins + 1e-8) - 0.5)
    priorities = tightness * balance_score
    return np.where(valid, priorities, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residuals = bins - item
    valid = residuals >= 0
    fill_ratio = item / (bins + 1e-8)
    priorities = np.exp(-((fill_ratio - 0.7) ** 2) / 0.1)
    return np.where(valid, priorities, -np.inf)
